args.sql:
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM information_schema.columns
             WHERE table_name = 'invoices' AND column_name = 'tax_rate')
  THEN
    ALTER TABLE invoices DROP COLUMN tax_rate;
  END IF;
END
$$;

